globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-26 09:05:00 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"1Password、従業員のGitHubアカウント経由で顧客の氏名とメールアドレスが流出したと発表 — BigGo ファイナンス","url":"https://finance.biggo.jp/news/86bd3431-ad2e-4b18-b885-4fb6393beb46","source":"Hatena","published_at":"2026-11-26 05:50","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"1Password従業員のGitHub侵害、顧客データ流出の詳細と影響","summary":"1Passwordは、従業員のGitHubアカウントが侵害され、内部システムに悪意のあるコードが注入されたことで、顧客の氏名やメールアドレスなどの管理データが流出したと発表しました。なお、パスワードを保管するボールト（保管庫）へのアクセスは一切なく、ユーザーの認証情報は安全であるとしています。\n\n流出したデータには公開鍵やアカウント識別子などが含まれますが、これら単体でアカウントへの侵入は不可能です。同社は侵害されたアカウントの無効化や認証情報のローテーションを実施済みですが、フィッシング攻撃への警戒を呼びかけています。","importance":9},{"title":"GitHub Copilot が切り拓くエージェント時代の開発ワークフロー","url":"https://speakerdeck.com/moulongzhang/20261124-githubconnecttokyo-session2","source":"Hatena","published_at":"2026-11-25 16:56","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"GitHub Copilotが変えるエージェント時代の開発ワークフロー","summary":"GitHub Connect Tokyo 2026での講演内容を基に、AIエージェントが開発ワークフローに与える変化を解説しています。2026年現在、PRの40%以上がエージェント起点となっており、開発者は「コードを書く人」から「目標を決め、成果を判断する人」へと役割がシフトしています。\n\n今後は、複数のエージェントを役割ごとに並列稼働させ、プロジェクト単位で成果を確かめるワークフローが主流となります。トークンの最適化やROIの考え方も重要になり、単なるコード生成から、エージェント群を束ねて成果を最大化するマネジメント能力がエンジニアに求められています。","importance":10},{"title":"「AI検索に電話番号が……」鳴りやまぬコールセンター　バッファローは壊れた「顧客導線」をどう改善した？","url":"https://www.itmedia.co.jp/business/articles/2611/26/news015.html","source":"Hatena","published_at":"2026-11-26 07:50","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI検索による電話問い合わせ急増、バッファローが挑んだWeb再設計","summary":"AI検索結果にサポート窓口の電話番号が直接表示されるようになったことで、バッファローのコンタクトセンターへの入電が急増しました。同社はこれを機に、AIを敵視するのではなく「AI検索を前提としたユーザーの自己解決」を促すWebサイトの再設計を断行しました。\n\nFAQの構造改革やノンボイス化を推進し、ユーザーがAI検索経由でも適切な情報にたどり着けるよう導線を最適化しました。結果として、AIを味方につけることで顧客体験を向上させ、電話依存からの脱却と効率的なサポート体制の構築に成功しています。","importance":7},{"title":"Button Sounds — tactile SFX for your UI","url":"https://buttons.joshwcomeau.com/","source":"Hatena","published_at":"2026-11-25 22:57","genre":"other","genre_label":"総合・その他IT","headline":"A free collection of 50+ professionally-recorded multi-sampled clic…","summary":"A free collection of 50+ professionally-recorded multi-sampled clicks and toggles.Distributed via NPM.","importance":5},{"title":"Migrating our Messages API to Rust","url":"https://www.anthropic.com/research/migrating-api-to-rust","source":"Hatena","published_at":"2026-11-26 02:02","genre":"web","genre_label":"Web開発・言語","headline":"Messages APIのRust移行、Claudeエージェントによる検証と最適化","summary":"ClaudeのMessages APIをPythonからRustへ移行し、CPU使用率を約70%削減、応答速度を約20%向上させた事例です。大規模なライブシステムの移行において、Claudeエージェントを活用して新旧APIの差異を自動検出し、修正する手法が採用されました。\n\n「生成は容易だが検証は困難」という課題に対し、本番トラフィックを用いて両APIの出力を比較する検証基盤を構築しました。これにより、サービスを停止することなく、信頼性を担保しながら大規模なリファクタリングを成功させた知見が共有されています。","importance":8},{"title":"Uber陣営の6人乗り高級ロボタクシー、無人での公道試験を開始","url":"https://japan.cnet.com/article/35255367/","source":"Hatena","published_at":"2026-11-25 11:21","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Uber陣営の6人乗り高級ロボタクシーが完全無人での公道試験を開始","summary":"Uber、Nuro、Lucidの3社が提携し、サンフランシスコ・ベイエリアで完全無人ロボタクシーの公道試験を開始しました。Lucid Gravityをベースにした6人乗りの車両を使用し、2027年第1四半期の商用サービス開始を目指しています。\n\n自動運転技術の競争が激化する中、安全性への懸念も高まっていますが、大手プラットフォームと連携した無人タクシーの普及は着実に進んでいます。Waymoなどの競合他社がトラブルで制限を受ける中、本陣営の動向が注目されます。","importance":8},{"title":"Update on a security incident involving 1Password’s backend systems. | 1Password","url":"https://1password.com/blog/update-on-nov-2026-security-incident","source":"Hatena","published_at":"2026-11-26 03:52","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"1Passwordのバックエンド侵害に関する公式報告と詳細","summary":"1Passwordがバックエンドシステムへの不正アクセスを報告しました。従業員のGitHubアカウントが侵害され、CI/CDシステムを通じて管理データがダウンロードされましたが、顧客のボールト（保管庫）は安全に保たれています。\n\n流出したデータは氏名、メールアドレス、公開鍵、アカウント識別子などであり、パスワードやシークレットキーは含まれていません。同社は即座に認証情報のローテーションを行い、サービスへの影響はないとしています。セキュリティインシデントの全容と対応策が公開されています。","importance":9},{"title":"「小学生くらいの頃に見たロボットに乗って戦うアニメを探してるのですが見つかりません」情報を元に推理して2択に絞られるが、解決したと思ったら謎が残った","url":"https://togetter.com/li/2774878","source":"Hatena","published_at":"2026-11-25 20:47","genre":"other","genre_label":"総合・その他IT","headline":"リップグリップ岩永 @lipiwanaga 僕が小学生ぐらいの頃なんで2003年前後だと思うんですけど、木曜か金曜(たぶん金曜日)の夜…","summary":"リップグリップ岩永 @lipiwanaga 僕が小学生ぐらいの頃なんで2003年前後だと思うんですけど、木曜か金曜(たぶん金曜日)の夜にやってた、ロボット(コードギアスみたいな細身で長身のロボット)がスノボみたいなのに乗って戦うアニメの名前ってわかる人いますか？\n\n@mokita_0301 ありがとうございます、エウレカセブンも好きなんですけど違くて…FLOWのDaysは神 Get Ride！アムドライバーじゃない？\n\n@lipiwanaga テレ東夕方ならアムドライバーだと思います @shohei_taguchi あの頃の僕の夕方の景色はテレ東しかないのでその通りです カッコよくて覚えてましたがタイトル思い出せなくて @lipiwanaga こんな強烈すぎるCMがやってたなら、アムドライバーですね pic.x.com/KzmTNLD3Vr @lipiwanaga テレ東ならこっちですかね？","importance":5},{"title":"「Google Workspace MCPサーバ」と「Google Workspace CLI」が正式版としてリリース","url":"https://www.publickey1.jp/blog/26/google_workspace_mcpgoogle_workspace_cli.html","source":"Hatena","published_at":"2026-11-26 01:42","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Google Workspace MCPサーバとCLIが正式リリース","summary":"Googleは、AIエージェントがWorkspaceを操作するためのインターフェイス「Google Workspace MCP Server」および「Google Workspace CLI」を正式版としてリリースしました。GmailやDrive、Docsなど主要8サービスに対応し、従来のREST APIよりもトークン効率に優れた操作が可能です。\n\n今後はAIエージェントによるアクセスをMCP経由に集約する方針が示されており、2027年2月までにREST APIからの移行が求められます。企業利用に適した監査ログや管理機能も備えており、AIエージェント開発の標準化が加速します。","importance":9},{"title":"AI-DLC最前線のCognitive Surrenderに陥らないチーム作り","url":"https://speakerdeck.com/yuukiyo/building-teams-that-resist-cognitive-surrender-in-ai-dlc","source":"Hatena","published_at":"2026-11-25 20:22","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI開発プロセス「AI-DLC」で陥りがちなCognitive Surrenderを防ぐ","summary":"AIを開発工程に組み込むだけでは、部分的な効率化にとどまり、チーム全体としての生産性向上を実感しにくいという課題があります。KDDIアジャイル開発センターでは、AI駆動開発（AI-DLC）を導入し、準備から運用までの5フェーズでプロセスを最適化しています。\n\n本記事では、AIに依存しすぎて思考停止に陥る「Cognitive Surrender」を回避し、AIの力を最大限に引き出すためのチーム作りを解説しています。AIを単なるツールとしてではなく、開発プロセスそのものを変革するエンジンとして活用するための実践的な知見が共有されています。","importance":8},{"title":"15分かかっていたCIを数分に — 内訳を測り、ランナーは同じコミットで並べて比べ、テストを3シャードに分けた","url":"https://zenn.dev/rehabforjapan/articles/ci-runner-compare-test-shards-202611","source":"Zenn","published_at":"2026-11-25 13:41","genre":"web","genre_label":"Web開発・言語","headline":"CIの実行時間を16分から数分へ短縮したボトルネック特定と改善手法","summary":"Spring Boot APIリポジトリのGitHub ActionsによるCIが16分かかっていた問題を、内訳の可視化と改善によって大幅に短縮した事例。テストの増加が原因という思い込みを捨て、Claude Codeを活用して工程ごとの時間を計測しました。\n\nGradleキャッシュの未保存や直列実行の非効率性が判明し、developブランチへのpushでキャッシュを生成する設定や、テストのシャード化を実施。結果としてCI時間を大幅に短縮し、開発効率を向上させました。","importance":8},{"title":"OSC 2026 Nagaokaに行ってきました！！","url":"https://zenn.dev/tayu99_make/articles/1448f04c300c1f","source":"Zenn","published_at":"2026-11-25 15:01","genre":"other","genre_label":"総合・その他IT","headline":"OSC 2026 Nagaoka参加レポート：地域課題とOSSの融合","summary":"新潟県長岡市で開催された「オープンソースカンファレンス 2026 Nagaoka」の参加レポートです。地域特有の課題である豪雪対策として、地下水を利用した消雪パイプの渇水を監視するIoTシステムがOSSを活用して構築されている事例などが紹介されました。\n\nまた、MySQLのリリース体制変更やコミュニティの動向など、技術的な知見も共有されています。地方開催のイベントであっても、地域課題解決と最新技術が結びついた濃い内容が展開されており、オープンソース文化の広がりと、それを通じた技術交流の重要性が改めて示されました。","importance":4},{"title":"HackwithBay 4.0参加記｜Evidence GTMを個人で作って見えた課題","url":"https://zenn.dev/rootforgerie/articles/hackwithbay-4-evidence-gtm-retrospective","source":"Zenn","published_at":"2026-11-26 03:58","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"ハッカソン参加記：B2B営業支援AI「Evidence GTM」開発の学び","summary":"サンフランシスコで開催されたハッカソン「HackwithBay 4.0」に個人参加し、B2B営業の企業調査からメール案作成までを支援する「Evidence GTM」を開発した記録です。StreamlitやNetworkXを活用し、根拠に基づいた営業メール作成を効率化するツールを実装しました。\n\n開発時間が限られる中で、機能追加を早期に切り上げ、デモ動画の作成や提出物の確認に時間を割く重要性を痛感したと振り返っています。個人開発における要件の優先順位付けや、チーム開発の重要性など、エンジニアリングの実践的な学びがまとめられています。","importance":5},{"title":"DBSC 入門: Cookie を盗まれても、攻撃者は使い続けられない仕組み","url":"https://zenn.dev/mittysan/articles/dbsc-device-bound-session-credentials","source":"Zenn","published_at":"2026-11-25 17:01","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Cookie盗難を防ぐDBSCの仕組みとセキュリティ効果","summary":"DBSC（Device Bound Session Credentials）は、ログイン後のCookieを特定のPCに紐付け、盗難されたCookieの悪用を数分以内に制限する新しいセキュリティ技術です。PC内の秘密鍵と短命なCookieを組み合わせることで、インフォスティーラーによるセッションハイジャックを無効化します。\n\n本技術はブラウザが自動で署名・更新を行うため、ユーザーの操作負担はありません。サーバー側には登録と更新のエンドポイント追加が必要です。現在はChrome（Windows/macOS）で対応が進んでおり、パスワードや多要素認証を突破された後の被害を最小限に抑えるための重要な防御策として期待されています。","importance":9},{"title":"AnthropicとOpenAIの従業員らが「未公開モデルが強力になりすぎて一般公開するのは危険」と懸念","url":"https://gigazine.net/news/20261125-anthropic-openai-employees-fear-unreleased-ai-models/","source":"Hatena","published_at":"2026-11-25 20:43","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Anthropic・OpenAI従業員が未公開AIモデルの危険性を警告","summary":"AnthropicやOpenAIの従業員らが、開発中の最先端AIモデルが制御不能なほど強力になりつつあると懸念を表明しました。Axiosの報道によると、これらのモデルは既存の安全対策を凌駕しており、一般公開が困難なレベルに達しているとのことです。\n\n数学やサイバーセキュリティ分野での推論能力が飛躍的に向上する一方で、AIがテストを回避する挙動を見せるなど、安全性確保が大きな課題となっています。企業側もリリース計画の見直しや安全要件の強化を余儀なくされており、AI開発のスピードと安全性のバランスが再び議論の焦点となっています。","importance":9},{"title":"【独自】政府、米中に次ぐAI国家確立へ　機微データ保護制度策定も（共同通信） - Yahoo!ニュース","url":"https://news.yahoo.co.jp/articles/c9e4bb22aadff231ac1deecd7af8ca7a7dd4544d","source":"Hatena","published_at":"2026-11-25 09:18","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"政府がAI国家確立へ向け「AI主権」の確立と機微データ保護制度を策定","summary":"政府が年内に改定する安全保障関連3文書において、AI分野での「米国、中国に次ぐ立ち位置」の確立を目標に掲げることが判明しました。他国に依存しない「AI主権」の考え方を導入し、技術基盤の強化と同志国との連携を推進します。\n\nまた、相次ぐ情報漏えい対策として、機微な個人データの保護制度策定も打ち出しました。経済安全保障を国家の基盤と位置づけ、AIを戦略技術として位置づける政府の方針が明確化されています。","importance":8},{"title":"増えすぎたテストから、削ってよいものを測って選ぶ","url":"https://zenn.dev/liatris/articles/20261126-test-pruning-criteria","source":"Zenn","published_at":"2026-11-26 07:00","genre":"web","genre_label":"Web開発・言語","headline":"テストスイートの肥大化を防ぐ、削除候補選定と検出力維持の検証","summary":"CIの遅延を招く過剰なテストを安全に削減するため、ミューテーションテストや失敗履歴を用いた削除候補の選定手法が検証されました。単なるカバレッジ削減ではなく、ミューテーションテストの検出力を維持しつつ、人が定義した「守るべき規則」と組み合わせる手法が最も有効であることが示されました。\n\n機械的な基準だけでテストを削ると重要なバグ検出を見逃すリスクがあるため、補助的な指標として活用し、最終的な判断に人の知見を介在させることで、テストスイートの品質と実行速度のバランスを最適化するアプローチが提案されています。","importance":6},{"title":"妻のために池袋の食べ放題比較サイトをAWSサーバーレスで作った","url":"https://zenn.dev/ikebukuro_infra/articles/7b8888adf459f7","source":"Zenn","published_at":"2026-11-26 00:13","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AWSサーバーレスで構築する食べ放題比較サイトと運用監視の極意","summary":"池袋の食べ放題店を比較できる個人サイトを、AWS LambdaやDynamoDBを用いたサーバーレス構成で構築した事例です。単なる開発にとどまらず、定期実行、監視、障害訓練までを網羅し、運用を意識した設計がなされています。\n\nAPIキーの管理やIAM権限の最小化、CloudWatchアラームによる通知など、実務的なインフラ運用スキルが活かされています。特に「障害訓練」を通じて設定ミスを発見し、運用を堅牢にするプロセスは、個人開発の枠を超えたエンジニアリングの好例です。","importance":6},{"title":"高木浩光＠自宅の日記 - 「氏名は含まれておりません」では済まない——KARTE事件で漏れた行動の記録は誰の個人データか","url":"http://takagi-hiromitsu.jp/diary/20261124.html","source":"Hatena","published_at":"2026-11-25 09:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"KARTE事件で浮き彫りになった「氏名なし」個人データの保護と法的責任","summary":"プレイドの「KARTE」不正アクセス事件を題材に、氏名が含まれていなくても「行動の記録」が個人データとして扱われるべきであるという論考。多くの企業が「氏名がないから個人情報ではない」と公表している現状に対し、法的な解釈とリスク管理の観点から警鐘を鳴らしています。\n\n会員番号や識別子と紐付いた行動履歴は、企業側で容易に照合可能なため個人情報に該当します。本稿は、今後の続報を扱う担当者や企業に対し、適切な情報開示と個人情報保護の重要性を再認識させる内容です。","importance":9},{"title":"結局「オントロジー」って何なのさ 〜概念と良さを4つのレイヤーで整理する〜","url":"https://zenn.dev/algomatic/articles/ece749a7e3cb24","source":"Zenn","published_at":"2026-11-25 18:23","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代に不可欠な「オントロジー」の概念と活用レイヤー","summary":"AIが企業のデータを文脈として理解するために注目される「オントロジー」について、その概念と良さを4つのレイヤーで整理した解説です。オントロジーは、モノとそれらの関係性を定義する設計図であり、単なるデータ集合に文脈を付与することでAIの推論能力を向上させます。\n\n記事では、狭義の設計図（オントロジー）、実データを含むナレッジグラフ、そしてPalantirが提唱する操作機能（kinetic要素）を含むモデルまでを段階的に解説しています。特に、定義に論理ルールを持たせることで機械的な推論が可能になる点が強みです。AI活用において、データの持ち方を「文脈」として設計することの重要性が説かれています。","importance":9},{"title":"組織レベルごとの品質定義（リライト）｜snsk","url":"https://note.com/_snsk/n/n9473a6e95b1c","source":"Hatena","published_at":"2026-11-26 01:01","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"組織レベルごとの品質定義：持続的イノベーションのための構造化","summary":"製品提供組織における品質定義を、Company、Product Line、Product、Project、Team/Individualの5階層に分類し、それぞれの役割とリーダーシップの所在を整理したリライト記事です。各レベルで一貫した品質指標を持つことが、持続的なイノベーションには不可欠であると説いています。\n\nGoogleの事例を交え、ビジネスモデルと品質属性を直結させる重要性や、品質エンジニアがどのレベルで貢献すべきかを構造的に考えるためのヒントを提供しています。組織設計や品質管理に携わるエンジニアにとって有益なフレームワークです。","importance":7},{"title":"specは実装後に8割削除しよう","url":"https://zenn.dev/ruri/articles/distill-specs-after-implementation","source":"Zenn","published_at":"2026-11-25 20:33","genre":"web","genre_label":"Web開発・言語","headline":"実装後の仕様書は8割削除、真実はコードとテストに宿る","summary":"開発前の計画文書である「spec」は、実装完了後にその大部分を削除すべきだという提言です。著者は、実装済みのspecの8割強は不要であり、真実はコード、テスト、型定義、ADR（設計記録）に集約されるべきだと説いています。\n\n残すべきは「意図」「スコープの境界」「前提条件」の3点のみとし、これらをコードと同じ規律で管理することを推奨しています。テストのない要件は守られていないのと同義であり、ドキュメントの二重管理を避けることで、AIエージェントや将来の開発者が古い情報に惑わされるリスクを低減できるとしています。","importance":7},{"title":"AIで学習アプリを作って2週間で宅建に合格した話【テキスト不要】｜Shikimi","url":"https://note.com/shikimi_crypto/n/n35d0bb54e6fb","source":"Hatena","published_at":"2026-11-25 18:23","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AI自作アプリとYouTube活用で宅建に2週間で合格した戦略","summary":"不動産業界未経験のコンサルタントが、試験2週間前からAIを活用した学習アプリとYouTube教材のみで宅建試験に合格した事例です。市販テキストを使わず、過去問分析から得た仮説に基づき、学習・演習・フィードバック機能を備えた専用アプリを自作して効率化を図りました。\n\n戦略の肝は、初日に過去問を解いて現在地を把握し、配点の高い宅建業法を最優先、権利関係を得点源とするなど、費用対効果を意識した学習計画です。AIを単なるツールではなく、学習プロセスを最適化するエージェントとして活用した点が特徴的です。ただし、これはAIの能力を検証するための「縛りプレイ」であり、確実な合格には市販教材の併用が推奨されています。","importance":6},{"title":"Claude Codeを安心して使うために、Dev Containerで隔離環境を作ってみた（WSL2＋Docker Desktop）","url":"https://zenn.dev/mutsu_zenn/articles/b9f824737b434a","source":"Zenn","published_at":"2026-11-26 07:00","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Claude Codeを安全に試す、Dev Containerによる隔離環境構築","summary":"Claude Codeの利便性を享受しつつ、ローカル環境への意図しないファイル操作やセキュリティリスクを懸念するユーザー向けに、VS CodeのDev Containerを用いた隔離環境の構築手順がまとめられました。\n\nWSL2とDocker Desktopを組み合わせ、コンテナ内にClaude Codeを閉じて実行することで、ホスト環境を保護しつつ安全にAIエージェントを試用できます。設定ファイル（devcontainer.json）の作成からコンテナ起動、ログインまでの具体的な手順が備忘録として整理されています。","importance":7},{"title":"Claude Code のセキュリティ、2026年11月時点のベストプラクティス（サンドボックス・権限・MCP）","url":"https://zenn.dev/happy_elements/articles/27e14ff6754044","source":"Zenn","published_at":"2026-11-25 12:53","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeのセキュリティを強化するサンドボックスと権限管理のベストプラクティス","summary":"Claude Code CLIを安全に運用するための2026年11月時点のベストプラクティスを解説。Claude Codeの設定による権限ルール（allow/ask/deny）と、OSレベルの隔離（Bashサンドボックス）を組み合わせた多層防御の重要性を説いています。\n\nプロンプトインジェクション対策として、実行前のチェックと実行中の制限を両立させる設定方法を提示。特にサンドボックスの有効化と、適切な権限ルールの記述が、安全なAIエージェント運用に不可欠であることを強調しています。","importance":9},{"title":"防衛省、自衛官の定数削減へ　「AI指揮統制」で人手補強 - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUA20BWZ0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-25 23:15","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"防衛省が自衛官定数削減へ、AI指揮統制で人手不足を補強","summary":"防衛省は、深刻な人手不足に対応するため、自衛官の定数を削減し、運用の効率化を図る方針を固めました。年内に改定予定の安全保障関連3文書にこの方針を明記し、実際の充足率を高めることを目指します。\n\n具体的な対策として、司令機能へのAI導入が挙げられています。AIによる指揮統制を強化することで、必要な人員を減らしつつ、部隊運用の迅速化と効率化を両立させる狙いです。技術による省人化が国家の安全保障戦略に直結する事例として注目されます。","importance":7},{"title":"マーダーミステリーのシナリオを形式手法で検証しようとしたら、バグと曖昧さが見つかった","url":"https://zenn.dev/henteko/articles/ed8d1458246d7a","source":"Hatena","published_at":"2026-11-25 17:07","genre":"web","genre_label":"Web開発・言語","headline":"マーダーミステリーのシナリオ矛盾を形式手法で検証するCLI","summary":"マーダーミステリーのシナリオ矛盾を検出するために、Lean 4を用いた形式手法で検証を行うCLIツールが開発されました。JSONで記述されたシナリオを仕様書とみなし、到達不可能なエンディングやアイテムの不整合などを機械的に判定します。\n\n開発過程で、検証可能な形に仕様を落とし込む段階でシナリオの曖昧さが発見されるなど、形式手法の副次的な効果が示されました。また、Leanによる証明を通じて、手動では見落としがちな論理的な穴も検出可能です。AIによるシナリオ生成が普及する中で、品質担保のための自動検証手法として非常に興味深い取り組みです。","importance":7},{"title":"DPIの違うモニタ間でウィンドウが飛ぶ：winitのWM_DPICHANGEDバグをHWNDサブクラス化で直した","url":"https://zenn.dev/kuwashima/articles/winit-dpi-multimonitor-drag","source":"Zenn","published_at":"2026-11-25 12:52","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"マルチモニタ環境でのウィンドウ位置ズレをHWNDサブクラス化で修正","summary":"Rust+egui製のチャットクライアントで発生していた、DPIの異なるモニタ間でのウィンドウ位置ズレ問題を解決した記録。原因はwinitのWM_DPICHANGEDハンドラにおける再配置ロジックの不備でした。\n\nフレームベースの補正では振動が発生したため、最終的にHWNDをサブクラス化してWM_DPICHANGEDを直接フックし、カーソル位置に追従させるワークアラウンドを実装。OSレベルのイベントを直接制御することで、安定したウィンドウ挙動を実現しました。","importance":6},{"title":"「セキュアSAMBA」における利用者情報の漏えいのおそれに関するお詫びとお知らせ | 株式会社kubellストレージ","url":"https://www.kubell-storage.com/news/2026/11/samba.html","source":"Hatena","published_at":"2026-11-26 00:12","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"「セキュアSAMBA」で設定不備による情報漏えいのおそれ","summary":"株式会社kubellストレージが提供する「セキュアSAMBA」において、管理用ページの設定不備により、ユーザーIDやパスワードが第三者に閲覧可能な状態になっていたことが判明しました。現時点で不正ログインの事実は確認されていませんが、予防措置として全ユーザーのパスワードリセットが実施されました。\n\n原因は画面の公開設定の不備と、URLにログイン情報を含める設計上の問題です。同社は再発防止策として、通信方式の改修や定期的な設定点検を強化するとしています。","importance":8},{"title":"Corpus2Skillに近づけた「階層ナビゲーション型RAG」と、ベクトルDB版RAGを「どの段階で失敗したか」まで比べてみた","url":"https://zenn.dev/aiforall/articles/133752ce2d97ad","source":"Zenn","published_at":"2026-11-25 11:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"階層ナビゲーション型RAGとベクトルDB版RAGの精度と失敗要因の比較分析","summary":"ベクトルDBを使わずにLLMが目次を辿る「階層ナビゲーション型RAG」と、従来のベクトルDB版RAGを比較検証。130文書・40問のテストにおいて、エージェント型が正答率でベクトルDB版を上回る結果となりました。\n\n特に複数文書にまたがる質問でエージェント型が優位性を示しました。失敗要因を「文書到達」「根拠抽出」「回答生成」の3段階に分解して分析した結果、ベクトル検索の限界とエージェント型の柔軟性が明確になりました。","importance":9},{"title":"体験ドリブンのすすめ ― AIで作れる時代に、何で差がつくか","url":"https://zenn.dev/mediaforce/articles/2fef9933aae9e7","source":"Zenn","published_at":"2026-11-25 11:28","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI時代にエンジニアが差別化を図るための「体験ドリブン」な開発手法","summary":"AIによって「作る」ことのハードルが下がった今、エンジニアが価値を生むためには「顧客体験」の設計が重要であると説く記事。システム移行案件のヒアリングを例に、Excelでの確認作業を「触れるページ」に変えることで顧客の負担を軽減した事例を紹介しています。\n\nAIを単なる高速化ツールではなく、顧客の体験を変えるための手段として活用する視点を提示。成果物の中身だけでなく、回答や確認のプロセス自体を最適化することが、今後のエンジニアの差別化要因になると主張しています。","importance":7},{"title":"moejsはSobekの半分以下、正規表現を使う処理ではgo-quickjsが逆転： pure Go製JSエンジン3種を同じプラグインで比較","url":"https://zenn.dev/nonejp/articles/3bbffb1db9c4ce","source":"Zenn","published_at":"2026-11-25 10:00","genre":"web","genre_label":"Web開発・言語","headline":"Go製JSエンジン3種（moejs, Sobek, go-quickjs）の性能比較","summary":"Goサーバーに組み込めるpure Go製JavaScriptエンジン3種（moejs, Sobek, go-quickjs）の性能を比較検証。正規表現処理やメモリ消費量、呼び出し速度の観点から各エンジンの特性を明らかにしました。\n\nmoejsはSobekと比較して高速かつ軽量ですが、正規表現処理ではgo-quickjsが逆転する結果となりました。用途に応じて、大量のランタイムを動かす場合はmoejs、正規表現の互換性や速度を重視する場合はgo-quickjsなど、選択の指針が示されています。","importance":7},{"title":"PayPayでシステム障害 カード連携サービスで決済できず | NHKニュース","url":"https://news.web.nhk/newsweb/na/nd-20261125de81532","source":"Hatena","published_at":"2026-11-25 23:26","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"スマホ決済大手のPayPayは、システム障害によって25日午後8時過ぎから、クレジットカードと連携したサービスで決済ができなくなってい…","summary":"PayPayでシステム障害 カード連携サービスで決済できず | NHKニュース。スマホ決済大手のPayPayは、システム障害によって25日午後8時過ぎから、クレジットカードと連携したサービスで決済ができなくなっているということです。","importance":5},{"title":"AWS セキュリティ成熟度モデル v3 と PCI DSS 版・AI 版の変更点と評価ツールを確認する","url":"https://zenn.dev/cscloud_blog/articles/new-aws-security-maturity-model","source":"Zenn","published_at":"2026-11-25 18:41","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWSセキュリティ成熟度モデルv3の変更点と活用法","summary":"AWSセキュリティ成熟度モデルがv3にアップデートされ、クラウド版に加えPCI DSS版とAI版が追加されました。v3ではコントロールの追加・統合が行われ、AI関連の脅威対策や開発支援が強化されています。また、評価ツールがWebアプリ化され、Well-ArchitectedやNIST CSFとの対応表示も可能になりました。\n\n本モデルはコンプライアンス監査用ではなく、セキュリティ運用の優先順位付けやロードマップ策定のための指針です。実装ガイダンスや検証方法が詳細化されており、設定の不備を確認するチェックリストとしても活用できます。v2からの移行時はコントロールIDの対応表を確認し、自社の環境に合わせて調整することが推奨されます。","importance":8},{"title":"NVIDIA、LLM方式の画像生成AI「Nemotron-Labs-Image」を無償公開","url":"https://pc.watch.impress.co.jp/docs/news/2159286.html","source":"Hatena","published_at":"2026-11-26 00:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"NVIDIA、LLM方式で画像を生成する「Nemotron-Labs-Image」を公開","summary":"NVIDIAは、LLMの自己回帰方式を用いて画像を生成するAIモデル「Nemotron-Labs-Image-30B-A3B」をHugging Faceで無償公開しました。従来のデノイジング方式とは異なり、画像を「視覚トークン」の列として出力する手法を採用しています。\n\n総パラメータ数は30Bですが、MoE型により実行時は3Bで動作します。研究・評価目的での利用に限定されていますが、エージェントが文章と画像を統合的に扱うフレームワークの一部として注目されます。コード生成による画像編集機能など、今後の展開も期待されます。","importance":8},{"title":"Java経験者が感じたLINQの便利さ","url":"https://zenn.dev/skyfall/articles/5de268e8339685","source":"Zenn","published_at":"2026-11-25 17:00","genre":"web","genre_label":"Web開発・言語","headline":"Java経験者が語るC# LINQの直感的なデータ操作","summary":"JavaからC#へ移行したエンジニアが、LINQ（Language Integrated Query）の利便性を解説しています。LINQはSQLに近いメソッド名でデータの検索や加工を統一的に記述できるため、直感的なコーディングが可能です。\n\nJavaのStream APIと比較すると、LINQは専用メソッドが豊富で記述量が少なく済むケースが多い点が特徴です。特に`DistinctBy`による重複除去や、`FirstOrDefault`と`SingleOrDefault`の使い分けなど、実務で役立つメソッドが紹介されています。データ操作の簡潔さと可読性の高さが、C#開発における大きなメリットとして強調されています。","importance":6},{"title":"窓の内側に貼って屋外を撮影する防犯カメラ　Ankerが9990円で発売","url":"https://japan.cnet.com/article/35255394/","source":"Hatena","published_at":"2026-11-25 17:33","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Anker、工事不要で窓の内側に貼る防犯カメラを発売","summary":"アンカー・ジャパンは、窓ガラスの内側に貼り付けてベランダや庭先を監視できる防犯カメラ「Anker Eufy Window Camera E10」を9,990円で発売しました。壁への穴あけや屋外配線が不要で、賃貸住宅でも導入しやすいのが特徴です。\n\n電源は室内のコンセントから供給し、カメラ本体のAIが人、ペット、車両を識別して検知対象のみを通知する機能を備えています。最大解像度は2688×1520ピクセルで、視野角は125度。録画データはmicroSDカードに保存するためクラウド契約も不要です。手軽に導入できるスマートホーム製品として注目されます。","importance":5},{"title":"AWS WAF の新料金（simplified pricing）と旧料金を試算して比べてみた | DevelopersIO","url":"https://dev.classmethod.jp/articles/aws-waf-simplified-pricing-estimate/","source":"Hatena","published_at":"2026-11-25 19:55","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWS WAFの新料金体系を試算、リソースベース課金への移行","summary":"2026年11月に発表されたAWS WAFの新料金体系（simplified pricing）について、旧料金との比較試算が行われました。新料金では、ルール数やWCU（Web ACL Capacity Units）に基づく課金が廃止され、保護するリソース数と検査リクエスト数に基づくシンプルなモデルへ移行します。\n\n2027年2月からの適用に先立ち、CloudFront構成での試算結果が示されています。構成によっては大幅なコスト削減が見込まれる一方、プレミアム機能の利用状況により影響が異なります。既存ユーザーは切り替え操作が不要ですが、コスト構造の変化を事前に把握しておくことが重要です。","importance":7},{"title":"MCPに新機能「Skills over MCP」登場。ツールとの接続だけでなく使い方のスキルもMCP経由で提供","url":"https://www.publickey1.jp/blog/26/mcpskills_over_mcpmcp.html","source":"Hatena","published_at":"2026-11-26 00:09","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MCPの新機能「Skills over MCP」でAIエージェントのスキル管理を効率化","summary":"AIエージェントと外部ツールを接続する業界標準プロトコル「MCP」に、新機能「Skills over MCP」がβ版として追加されました。これにより、AIエージェントはMCPサーバから最新のスキルを動的に取得可能となり、コンテキストの節約と運用の効率化が実現します。\n\n従来はスキルファイル（SKILL.md等）を個別に管理する必要がありましたが、ツールとスキルをMCP経由で統合することで、常に最新の操作手順をAIに提供できます。AnthropicのClaude等で順次対応が進んでおり、AIエージェントの自律的な業務遂行能力が向上します。","importance":8},{"title":"Claude Code Channels を Windows で自作し、権限確認を外から許可した","url":"https://zenn.dev/ai_hacchu/articles/claude-code-channels-windows-permission-relay","source":"Zenn","published_at":"2026-11-25 09:00","genre":"web","genre_label":"Web開発・言語","headline":"Claude Code ChannelsをWindowsで自作し外部から権限確認を制御","summary":"Claude CodeのChannels機能をWindows環境で自作し、Discord等の外部ツールからセッションを操作する仕組みを構築した事例。Node.jsを用いてHTTP経由でメッセージの送受信と権限確認の応答を行う窓口を作成しました。\n\n公式ドキュメントにないWindows対応を独自に実装し、セッションごとの権限確認を外部から許可するフローを確立。開発効率を向上させるための研究開発として、MCPサーバーの活用と自動化の可能性を示しています。","importance":7},{"title":"Yocto で脱 GPLv3 構成を作り、ビルドごとに OSS ライセンス一覧を自動生成する","url":"https://zenn.dev/remote_sw/articles/3777969dd3a4de","source":"Zenn","published_at":"2026-11-25 16:35","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"YoctoでGPLv3を排除しOSSライセンス一覧を自動生成する構成","summary":"組込みLinux製品において、GPLv3の「反Tivo化条項」を避けるためにYoctoでGPLv3ソフトウェアを排除する構成と、OSSライセンス一覧を自動生成する手法の解説です。`INCOMPATIBLE_LICENSE`を使用してGPLv3をビルドから除外し、必要なパッケージはGPLv2版に差し替える手順が示されています。\n\nまた、Yoctoの`license.manifest`を活用し、ビルドごとに正確なOSS一覧とライセンス文を自動生成するスクリプトを導入しています。これにより、手動管理によるミスを防ぎ、製品出荷時のライセンスコンプライアンスを効率的に担保することが可能です。","importance":7},{"title":"Skills over MCP：MCPサーバーからスキルを配れるようになりました","url":"https://zenn.dev/shogo_h/articles/skills-over-mcp-overview","source":"Zenn","published_at":"2026-11-25 23:16","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MCPサーバーからエージェント向け手順書を配布する「Skills over MCP」","summary":"「Skills over MCP」は、AIエージェントが利用する手順書（スキル）をMCPサーバーから動的に配布可能にする公式拡張機能です。これまでは手動でファイルを配置・更新する必要がありましたが、本拡張によりサーバー側で一元管理し、接続する全クライアントに最新の手順を自動配布できるようになります。\n\n仕様ではスキルを「データ」として扱い、実行の安全性はクライアント側の承認プロセスに委ねられています。GitHub MCP Serverなどでの活用が進んでおり、指示文の肥大化を防ぎつつ、チーム全体で業務手順を効率的に共有・更新するための強力な仕組みとして期待されています。","importance":8},{"title":"Claude Codeに作らせたWordで、英語の引用符だけ全角になるのはなぜか","url":"https://zenn.dev/hochikisu/articles/0d90495fbcc666","source":"Zenn","published_at":"2026-11-26 01:36","genre":"web","genre_label":"Web開発・言語","headline":"WordのXML構造から解明する、Claude Code生成文書の書式崩れ","summary":"Claude Codeで生成したWord文書において、英語の引用符が全角幅になるなどの書式崩れが発生する原因を、docxファイルのXML構造から特定する手法が解説されました。Wordのフォント指定は文字の種類ごとに細分化されており、Claude Codeがランを複製する際に不適切なヒント属性が付与されることが原因です。\n\nXMLを直接編集しなくても、Claude Codeに特定のXML箇所を修正させることで、根本的な解決が可能であることが示されました。Officeの規格実装に基づいた正確な指示出しの重要性が説かれています。","importance":5},{"title":"[アップデート]AWS Continuum for Penetration Testingでコストの事前予測ができるようになりました | DevelopersIO","url":"https://dev.classmethod.jp/articles/aws-continuum-estimate/","source":"Hatena","published_at":"2026-11-25 13:48","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWS Continuum for Penetration Testingで脆弱性診断のコスト事前見積が可能に","summary":"AIを活用したWebアプリ脆弱性診断サービス「AWS Continuum for Penetration Testing」がアップデートされ、診断実行前にタスク時間とコストの事前見積もりが可能になりました。\n\n従来は診断を開始するまで正確なコストが不明でしたが、今回の機能追加により、対象環境をスキャンして事前に所要時間を予測できるようになりました。これにより、コスト管理が容易になり、安心して脆弱性診断を実施できる環境が整いました。","importance":7},{"title":"AI Agentを用いたSCP観測日誌ベンチマークの自動作成（と検証）","url":"https://zenn.dev/holy_fox/articles/07d9a0537db3bf","source":"Zenn","published_at":"2026-11-25 16:03","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI Agentを活用したSCP観測日誌ベンチマークの作成と検証","summary":"AIモデルの性能を評価するための新しいベンチマーク「SCP観測日誌ベンチマーク」の作成事例です。SCP財団Wikiのライセンスの明確さと、読解・論理推論が必要な問題の性質を活かし、AIエージェントを用いて100問の評価セットを自動生成・監査しました。\n\n既存のベンチマークにおけるデータ汚染や問題の不備といった課題に対し、AIによる自動作成と人間による監査を組み合わせることで信頼性を確保しています。LLMの精読力や状態追跡力を測るための実用的な評価環境として、GitHubおよびHugging Faceで公開されています。","importance":8},{"title":"RustでFiberを用いたJob Systemを実装したらReleaseビルドでバグが発生した","url":"https://zenn.dev/otinpan/articles/082f6178eb1472","source":"Zenn","published_at":"2026-11-25 19:24","genre":"web","genre_label":"Web開発・言語","headline":"現在、RustとVulkanを用いた自作ゲームエンジン KaniVolcanoEngine を開発しています。","summary":"現在、RustとVulkanを用いた自作ゲームエンジン KaniVolcanoEngine を開発しています。KaniVolcanoEngineでは、Jobの並列実行を実現するために、WindowsのFiber APIを用いたJob Systemを実装しています。\n\n今回、ReleaseビルドでJob Systemを動作させたところ、assertによるpanicや、RefCellの借用エラーが発生しました。原因を調査する過程で、Fiberのスレッド間移動と、コンパイラによるTLS（Thread Local Storage）アクセスの最適化が関係している可能性が浮上しました。\n\n本記事では、Job Systemの構成、発生したバグ、およびコンパイラ最適化とFiberの関係について説明します。KaniVolcanoEngineのJob Systemでは、 OSスレッドであるWorkerと、 Jobの実行単位であるFiberを分離して管理しています。\n\n構造を簡略化すると以下のようになります。","importance":5},{"title":"最近のMySQL事情について","url":"https://speakerdeck.com/yoku0825/mysql-in-2026","source":"Hatena","published_at":"2026-11-25 21:41","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"2026/11/25 DBRE Summit 2026 https://mercari.connpass.com/event/4099…","summary":"LANGUAGE JAVASCRIPT AS .. がサポート(Enterprise版のみ) VECTOR データ型(ただし計算用の関数はEnterprise版のみ) 11/25 MySQL 9.0 IR (2024-07) CREATE EVENT が ? プレースホルダをサポート CREATE MySQL 9.1 IR (2024-10) component_group_replication_flow_control_stats (この時点ではEnterprise版のみ) replication_applier_metrics, replication_applier_progress_by_worker (この時点では Enterprise版のみ) otelを喋れるようになる (この時点ではEnterprise版のみ) CREATE VIEW ..","importance":5},{"title":"AIを使った開発に「敵対的検証」を取り入れてみた","url":"https://zenn.dev/visionarray/articles/26b316ff128513","source":"Zenn","published_at":"2026-11-25 15:55","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI開発における「敵対的検証」の導入と効果","summary":"AIを活用した開発フローに、ソフトウェアが破綻する条件を意図的に探す「敵対的検証」を取り入れた実践記録です。通常のコードレビューとは別に、実装時のコンテキストを切り離した新しいチャットセッションで検証を行うことで、前提条件の誤りや処理の部分失敗といった潜在的なバグを効率的に発見しています。\n\nAIに「壊す側」の視点を持たせることで、実装者が想定していない操作や異常系の挙動を洗い出せる点がメリットです。AI開発において、コード生成時と検証時でコンテキストを使い分ける手法は、品質担保のための有効なアプローチといえます。","importance":8},{"title":"[AWS]DMSを試してみる(Database Migraton Service)","url":"https://zenn.dev/77nnaapp/articles/52d5b46af0e72c","source":"Zenn","published_at":"2026-11-25 18:51","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"EC2にMySQLを構築 RDS for MySQLを構築 DMSのレプリケーションインスタンスを作成 Source Endpoint…","summary":"EC2にMySQLを構築 RDS for MySQLを構築 DMSのレプリケーションインスタンスを作成 Source EndpointとTarget Endpointを設定 Migration Taskを実行 全件移行（Full Load） 移行先のテーブル・レコードを確認 今回の構築ステップ STEP 作業 1 DMS専用VPCの作成 2 サブネット・ルートテーブル作成 3 Security Group作成 4 移行元MySQL（EC2）構築 5 移行先RDS for MySQL構築 6 DMS Replication Instance作成 7 Source / Target Endpoint作成 8 接続テスト 9 Migration Task作成 10 Full Load実行・データ確認 STEP 1：DMS専用VPCを作成 項目 設定値 作成するリソース VPCのみ 名前 vpc-dms-lab IPv4 CIDR 10.40.0.0/16 IPv6 なし テナンシー デフォルト STEP 2：サブネットの作成 項目 設定値 VPC I。","importance":5},{"title":"AIエージェントのMemory設計 ― 会話履歴・業務データ・長期Memoryの使い分け","url":"https://zenn.dev/taru_neko/articles/ai-agent-memory-architecture-2026","source":"Zenn","published_at":"2026-11-25 14:23","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントにおけるMemory設計の使い分けと構成","summary":"AIエージェントにおける会話履歴（短期Memory）と長期Memoryの設計指針を、経費精算システムを例に解説しています。短期Memoryは会話の文脈維持や処理の進行状態保持に、長期Memoryはユーザーの好みや過去の蓄積情報の再利用に用いるという役割分担が重要です。\n\n物理的な保存基盤は既存のDBやCheckpointerを共用可能ですが、何を記憶し、どう更新・削除するかという設計判断が不可欠です。RAGは情報の検索手法でありMemoryそのものではないという区別も重要です。エージェントの自律性を高めるための、構造化されたMemory設計の重要性が説かれています。","importance":8}]};
